          en: "What makes it beautiful: words with the same ending give nice music: as-samaa', al-wafaa', al-ikhaa', al-ataa'. “Our manners are beautiful like the sun”: the poet compares manners to the sun. “Our manners are treasures”: comparing manners to treasures shows how valuable they are.",
          uk: "Що робить вірш гарним: слова з однаковим закінченням звучать як музика: ас-сама', аль-вафа', аль-іха', аль-ата'. «Наші чесноти прекрасні, як сонце»: поет порівнює чесноти із сонцем. «Наші чесноти — скарби»: порівняння зі скарбами показує, які вони цінні.",
