        ar: "التَّنْوِينُ: نُونٌ زَائِدَةٌ تَلْحَقُ بِآخِرِ الِاسْمِ نُطْقًا لَا كِتَابَةً. أَنْوَاعُهُ: تَنْوِينُ الضَّمِّ (ٌ)، تَنْوِينُ الْفَتْحِ (ً)، تَنْوِينُ الْكَسْرِ (ٍ). لَاحِظْ: التَّنْوِينُ يَكُونُ فِي الْأَسْمَاءِ فَقَطْ، وَلَا يَدْخُلُ عَلَى الْأَفْعَالِ وَلَا الْحُرُوفِ، مِثْلُ: كِتَابٌ – قَلَمًا – مَدْرَسَةٍ. الِاسْمُ الَّذِي دَخَلَتْ عَلَيْهِ «الْ» التَّعْرِيفِ لَا يُنَوَّنُ: الْكِتَابُ وَلَيْسَ الْكِتَابٌ. التَّنْوِينُ بِالْفَتْحِ عَلَى التَّاءِ الْمَرْبُوطَةِ لَا نَضَعُ بَعْدَهُ أَلِفًا: شَجَرَةً وَلَيْسَ شَجَرَةًا.",
        en: "Tanween is an extra “n” sound at the end of a noun: you SAY it but don't WRITE it. Kinds: -un (ٌ), -an (ً), -in (ٍ). Only nouns have tanween, never verbs or little words. A word with ال has no tanween (الكتابُ, not الكتابٌ). After ة we write -an without alif (شجرةً, not شجرةًا).",
        uk: "Танвін — додатковий звук «н» у кінці іменника: його ВИМОВЛЯЄМО, але НЕ ПИШЕМО. Види: ‑ун (ٌ), ‑ан (ً), ‑ін (ٍ). Танвін буває лише в іменниках, не в дієсловах і не в службових словах. Слово з ال не має танвіну (الكتابُ, а не الكتابٌ). Після ة пишемо ‑ан без аліфа (شجرةً, а не شجرةًا).",
